// Generated by schema/packet-generate.mjs from packet-v2.schema.json.
export type BeamPacket = {
  version: 2;
  beamId: string;
  source: string;
  title: string;
  updatedAt: string;
  completed: boolean;
  truncated?: boolean;
  sourceModel?: {
    provider: string;
    model: string;
  };
  items: {
    type: "userMessage" | "agentMessage" | "other";
    text: string;
    speaker?: string;
  }[];
};

export const BEAM_PACKET_ABI = 2;
const MAX_PACKET_BYTES = 56 * 1024;

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isInstant(text: string): boolean {
  const m =
    /^(\d{4})-(\d{2})-(\d{2})T([01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d{1,9})?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)(?![\s\S])/.exec(
      text,
    );
  if (!m) {
    return false;
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const lastDay = days[month - 1];
  return lastDay !== undefined && day >= 1 && day <= lastDay;
}

// JSON.parse has already checked syntax. Walk the raw string tokens remaining
// after decoding to catch duplicate (including escaped) keys and lone surrogates.
function distinctKeysAndScalars(text: string): boolean {
  const stack: (Set<string> | undefined)[] = [];
  const tokens = /"(?:[^"\\]|\\.)*"|[{}[\]]/g;
  for (const token of text.matchAll(tokens)) {
    const value = token[0];
    if (value === "{") {
      stack.push(new Set());
      continue;
    }
    if (value === "[") {
      stack.push(undefined);
      continue;
    }
    if (value === "}" || value === "]") {
      stack.pop();
      continue;
    }
    const decoded: string = JSON.parse(value);
    if (/[\uD800-\uDFFF]/u.test(decoded)) {
      return false;
    }
    let at = token.index + value.length;
    while (/[ \t\n\r]/.test(text.charAt(at))) {
      at++;
    }
    if (text.charAt(at) !== ":") {
      continue;
    }
    const keys = stack[stack.length - 1];
    if (!keys || keys.has(decoded)) {
      return false;
    }
    keys.add(decoded);
  }
  return true;
}

export function parseBeamPacket(bytes: Uint8Array): BeamPacket {
  if (bytes.byteLength > MAX_PACKET_BYTES) {
    throw new Error("Beam packet exceeds 56 KiB");
  }
  try {
    const text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
    const value: unknown = JSON.parse(text);
    if (distinctKeysAndScalars(text) && conforms(value)) {
      return value;
    }
  } catch {
    // JSON.parse error strings may contain transcript text. Keep it out of diagnostics.
  }
  throw new Error("invalid Beam v2 packet");
}

function conforms(value: unknown): value is BeamPacket {
  return (
    record(value) &&
    Object.keys(value).every((key) =>
      [
        "version",
        "beamId",
        "source",
        "title",
        "updatedAt",
        "completed",
        "truncated",
        "sourceModel",
        "items",
      ].includes(key),
    ) &&
    value.version === 2 &&
    typeof value.beamId === "string" &&
    value.beamId.length === 32 &&
    /^[0-9a-f]{32}(?![\s\S])/u.test(value.beamId) &&
    typeof value.source === "string" &&
    value.source.length >= 1 &&
    value.source.length <= 32 &&
    /^[a-z0-9._-]+(?![\s\S])/u.test(value.source) &&
    typeof value.title === "string" &&
    value.title.length <= 160 &&
    /\S/u.test(value.title) &&
    typeof value.updatedAt === "string" &&
    value.updatedAt.length <= 64 &&
    isInstant(value.updatedAt) &&
    typeof value.completed === "boolean" &&
    (value.truncated === undefined || typeof value.truncated === "boolean") &&
    (value.sourceModel === undefined ||
      (record(value.sourceModel) &&
        Object.keys(value.sourceModel).every((key) => ["provider", "model"].includes(key)) &&
        typeof value.sourceModel.provider === "string" &&
        value.sourceModel.provider.length >= 1 &&
        value.sourceModel.provider.length <= 64 &&
        /^[a-z0-9._-]+(?![\s\S])/u.test(value.sourceModel.provider) &&
        typeof value.sourceModel.model === "string" &&
        value.sourceModel.model.length >= 1 &&
        value.sourceModel.model.length <= 256 &&
        !/\s/u.test(value.sourceModel.model))) &&
    Array.isArray(value.items) &&
    value.items.length >= 1 &&
    value.items.length <= 200 &&
    value.items.every(
      (item: unknown) =>
        record(item) &&
        Object.keys(item).every((key) => ["type", "text", "speaker"].includes(key)) &&
        (item.type === "userMessage" || item.type === "agentMessage" || item.type === "other") &&
        typeof item.text === "string" &&
        item.text.length <= 6000 &&
        /\S/u.test(item.text) &&
        (item.speaker === undefined ||
          (typeof item.speaker === "string" &&
            /^p([1-9]|[1-9][0-9]|1[0-9]{2}|200)(?![\s\S])/u.test(item.speaker))) &&
        (item.speaker === undefined || item.type === "userMessage"),
    )
  );
}
